// Command aotcheck runs the AOT test programs of testdata/aot in several
// execution modes and compares their output with `go run`:
//
//	go      go run (reference output and native compiled performance)
//	native  VM, the library under test called natively (the reflect wall)
//	interp  VM, the library under test interpreted from source (-opaque)
//	aot     VM, every package generated by cmd/aotgen in AOT mode (-aot)
//	fallback VM in AOT mode, but every package of the modules of the
//	        library under test interpreted from source: what a plugin gets
//	        when it vendors another version of the library (the AOT copy
//	        is then not used, vm/aotsource.go). Standard library programs
//	        are skipped (a plugin cannot vendor them).
//
// With -bench, each mode also runs the program's benchOp in a loop
// (AOT_BENCH=n) and reports the cost per call: the iteration count is
// calibrated so that a run lasts about 200 ms, then -reps runs are made and
// the minimum is reported (the median and the spread go to the TSV).
//
// A program declares the library it tests with a line `//aot:lib path...`.
package main

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Result is the outcome of one program in one mode.
type Result struct {
	File, Mode string
	Status     string // MATCH, DIFF, FAIL (non-zero exit), UNSUP (VM: unsupported construct), SKIP
	Detail     string
	NsOp       int64 // -bench: cost per call, minimum over the repetitions (0: not measured)
	NsMed      int64 // -bench: median over the repetitions
	Spread     int   // -bench: (max-min)/min over the repetitions, in percent
	Output     string
}

// Program is a test program of testdata/aot.
type Program struct {
	Path string
	Libs []string
	Std  bool // all libraries are standard library packages
}

var allModes = []string{"go", "native", "interp", "aot", "fallback"}

// interpDeps are interpreted with the library in the interp mode.
var interpDeps = []string{"fmt", "errors", "sort", "slices", "strconv", "internal/strconv", "internal/fmtsort", "internal/stringslite"}

func main() {
	modes := flag.String("modes", strings.Join(allModes, ","), "modes to run")
	bench := flag.Bool("bench", false, "measure the cost per call of each program's benchOp")
	reps := flag.Int("reps", 5, "-bench: measured runs per program and mode")
	run := flag.String("run", "", "only programs matching this regexp")
	jobs := flag.Int("j", runtime.NumCPU()/2, "parallel runs")
	tsv := flag.String("tsv", "", "write the results as TSV to this file")
	verbose := flag.Bool("v", false, "print diffs")
	flag.Parse()
	root, err := FindRoot()
	if err != nil {
		fatal(err)
	}
	progs, err := Discover(filepath.Join(root, "testdata", "aot"), *run)
	if err != nil {
		fatal(err)
	}
	yaegiBin := filepath.Join(os.TempDir(), "aotcheck-yaegi")
	if err := BuildVM(root, yaegiBin); err != nil {
		fatal(err)
	}
	cfg := Config{Root: root, VM: yaegiBin, Bench: *bench, Reps: *reps, Modes: strings.Split(*modes, ","), Jobs: *jobs}
	results := Run(cfg, progs)
	PrintTable(os.Stdout, cfg.Modes, progs, results, *bench)
	if *verbose {
		for _, r := range results {
			if r.Status != "MATCH" && r.Mode != "go" && r.Detail != "" {
				fmt.Printf("\n--- %s [%s] %s\n%s\n", filepath.Base(r.File), r.Mode, r.Status, r.Detail)
			}
		}
	}
	if *tsv != "" {
		if err := WriteTSV(*tsv, results); err != nil {
			fatal(err)
		}
	}
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "aotcheck:", err)
	os.Exit(1)
}

// Env is the environment of every run (module cache only, no network).
func Env(extra ...string) []string {
	return append(append(os.Environ(), "GOFLAGS=-mod=mod", "GOPROXY=off", "GOSUMDB=off"), extra...)
}

// FindRoot returns the root of the yaegi v2 module.
func FindRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if b, err := os.ReadFile(filepath.Join(dir, "go.mod")); err == nil && bytes.Contains(b, []byte("module github.com/traefik/yaegi/v2\n")) {
			return dir, nil
		}
		p := filepath.Dir(dir)
		if p == dir {
			return "", errors.New("yaegi v2 module root not found")
		}
		dir = p
	}
}

// BuildVM builds cmd/yaegi.
func BuildVM(root, out string) error {
	cmd := exec.Command("go", "build", "-o", out, "./cmd/yaegi")
	cmd.Dir, cmd.Env = root, Env()
	if b, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("building yaegi: %v\n%s", err, b)
	}
	return nil
}

var libRE = regexp.MustCompile(`(?m)^//aot:lib (.+)$`)

// Discover lists the programs of dir.
func Discover(dir, filter string) ([]Program, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return nil, err
	}
	var re *regexp.Regexp
	if filter != "" {
		if re, err = regexp.Compile(filter); err != nil {
			return nil, err
		}
	}
	var out []Program
	for _, f := range files {
		if re != nil && !re.MatchString(filepath.Base(f)) {
			continue
		}
		b, err := os.ReadFile(f)
		if err != nil {
			return nil, err
		}
		p := Program{Path: f, Std: true}
		if m := libRE.FindSubmatch(b); m != nil {
			p.Libs = strings.Fields(string(m[1]))
		}
		for _, l := range p.Libs {
			first, _, _ := strings.Cut(l, "/")
			if strings.Contains(first, ".") {
				p.Std = false
			}
		}
		out = append(out, p)
	}
	return out, nil
}

// Config configures Run.
type Config struct {
	Root, VM string
	Bench    bool
	Reps     int
	Modes    []string
	Jobs     int
	Timeout  time.Duration
}

// Run runs every program in every mode and compares with the go mode.
func Run(cfg Config, progs []Program) []Result {
	if cfg.Timeout == 0 {
		cfg.Timeout = 120 * time.Second
	}
	if cfg.Jobs < 1 {
		cfg.Jobs = 1
	}
	type job struct {
		p    Program
		mode string
	}
	var jobs []job
	for _, p := range progs {
		for _, m := range cfg.Modes {
			jobs = append(jobs, job{p, m})
		}
	}
	results := make([]Result, len(jobs))
	sem := make(chan struct{}, cfg.Jobs)
	var wg sync.WaitGroup
	for i, j := range jobs {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			results[i] = runOne(cfg, j.p, j.mode, "")
		}()
	}
	wg.Wait()
	// Compare with the reference.
	ref := map[string]*Result{}
	for i := range results {
		if results[i].Mode == "go" {
			ref[results[i].File] = &results[i]
		}
	}
	if len(ref) == 0 {
		for _, p := range progs {
			r := runOne(cfg, p, "go", "")
			ref[p.Path] = &r
		}
	}
	for i := range results {
		r := &results[i]
		want := ref[r.File]
		if r.Mode == "go" {
			if r.Status == "" {
				r.Status = "ref"
			}
			continue
		}
		if r.Status != "" || want == nil {
			continue
		}
		switch {
		case want.Status == "FAIL":
			r.Status, r.Detail = "SKIP", "go run fails: "+want.Detail
		case r.Output == want.Output:
			r.Status = "MATCH"
		default:
			r.Status, r.Detail = "DIFF", Diff(want.Output, r.Output)
		}
	}
	if cfg.Bench {
		byPath := map[string]Program{}
		for _, p := range progs {
			byPath[p.Path] = p
		}
		// Sequentially, for stable timings.
		for i := range results {
			r := &results[i]
			if r.Status == "MATCH" || r.Status == "ref" || r.Status == "DIFF" {
				r.NsOp, r.NsMed, r.Spread = bench(cfg, byPath[r.File], r.Mode)
			}
		}
	}
	return results
}

// args returns the command running p in mode.
func args(cfg Config, p Program, mode string) (string, []string, []string, bool) {
	switch mode {
	case "go":
		return "go", []string{"run", p.Path}, nil, true
	case "native":
		var ms []string
		for _, l := range p.Libs {
			ms = append(ms, l+"=native")
		}
		return cfg.VM, []string{"-mode", strings.Join(ms, ","), p.Path}, nil, true
	case "interp":
		// The library and the reflect-using stdlib packages it hands user
		// values to are interpreted (VM-internal reflect, -opaque).
		var ms []string
		for _, l := range append(append([]string{}, p.Libs...), interpDeps...) {
			ms = append(ms, l+"=interp")
		}
		return cfg.VM, []string{"-opaque", "-mode", strings.Join(ms, ","), p.Path}, nil, true
	case "aot":
		return cfg.VM, []string{"-aot", p.Path}, nil, true
	case "fallback":
		ms, err := fallbackModes(cfg.Root, p)
		if err != nil || len(ms) == 0 {
			return "", nil, nil, false
		}
		return cfg.VM, []string{"-aot", "-mode", strings.Join(ms, ","), p.Path}, nil, true
	}
	return "", nil, nil, false
}

// fallbackModes returns the -mode list of the fallback mode: path=interp
// for every package that p imports, directly or not, from the modules of
// its libraries. When a plugin vendors another version of a module, the
// version check refuses the AOT copies of all its packages.
func fallbackModes(root string, p Program) ([]string, error) {
	cmd := exec.Command("go", "list", "-deps", "-f", "{{if .Module}}{{.ImportPath}} {{.Module.Path}}{{end}}", p.Path)
	cmd.Dir, cmd.Env = root, Env()
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("go list -deps %s: %v", p.Path, err)
	}
	modOf := map[string]string{}
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if path, mod, ok := strings.Cut(line, " "); ok {
			modOf[path] = mod
		}
	}
	libMods := map[string]bool{}
	for _, l := range p.Libs {
		if mod := modOf[l]; mod != "" && mod != "github.com/traefik/yaegi/v2" {
			libMods[mod] = true
		}
	}
	var ms []string
	for path, mod := range modOf {
		if libMods[mod] {
			ms = append(ms, path+"=interp")
		}
	}
	sort.Strings(ms)
	return ms, nil
}

func runOne(cfg Config, p Program, mode, benchN string) Result {
	r := Result{File: p.Path, Mode: mode}
	if mode == "fallback" && p.Std {
		r.Status, r.Detail = "SKIP", "standard library: a plugin cannot vendor another version"
		return r
	}
	name, argv, env, ok := args(cfg, p, mode)
	if !ok {
		r.Status, r.Detail = "SKIP", "unknown mode"
		return r
	}
	if benchN != "" {
		env = append(env, "AOT_BENCH="+benchN)
	}
	ctx, cancel := context.WithTimeout(context.Background(), cfg.Timeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, argv...)
	cmd.Dir = cfg.Root
	cmd.Env = Env(env...)
	out, err := cmd.CombinedOutput()
	r.Output = string(out)
	if err != nil {
		code := -1
		var ee *exec.ExitError
		if errors.As(err, &ee) {
			code = ee.ExitCode()
		}
		if ctx.Err() != nil {
			r.Status, r.Detail = "FAIL", "timeout"
			return r
		}
		if mode == "go" {
			r.Status, r.Detail = "FAIL", lastLines(r.Output, 5)
			return r
		}
		// A failing run still matches if go run fails the same way, which
		// the comparison decides; but VM-specific failures are classified.
		if code == 3 || code == 4 {
			r.Status, r.Detail = "UNSUP", lastLines(r.Output, 3)
		}
		if r.Status == "" {
			r.Detail = fmt.Sprintf("exit %d", code)
		}
	}
	return r
}

// bench measures the cost per call of benchOp in mode (ns): the iteration
// count is calibrated so that a run lasts about 200 ms, then cfg.Reps runs
// are measured; it returns their minimum (the least disturbed run), their
// median and their spread in percent. Each run is a new process: it includes
// the program's first call (warm-up, not timed) but not its loading.
func bench(cfg Config, p Program, mode string) (best, med int64, spread int) {
	n := 20
	for range 5 {
		r := runOne(cfg, p, mode, strconv.Itoa(n))
		ns := parseBench(r.Output)
		if ns <= 0 {
			return 0, 0, 0
		}
		if int64(n)*ns > 100_000_000 || n >= 1_000_000 {
			break
		}
		n = int(min(max(200_000_000/max(ns, 1), int64(n)*2), 1_000_000))
	}
	reps := max(cfg.Reps, 1)
	var ns []int64
	for range reps {
		x := parseBench(runOne(cfg, p, mode, strconv.Itoa(n)).Output)
		if x <= 0 {
			return 0, 0, 0
		}
		ns = append(ns, x)
	}
	sort.Slice(ns, func(i, j int) bool { return ns[i] < ns[j] })
	return ns[0], ns[len(ns)/2], int((ns[len(ns)-1] - ns[0]) * 100 / ns[0])
}

func parseBench(out string) int64 {
	sc := bufio.NewScanner(strings.NewReader(out))
	for sc.Scan() {
		if f := strings.Fields(sc.Text()); len(f) == 2 && f[0] == "BENCH" {
			n, _ := strconv.ParseInt(f[1], 10, 64)
			return n
		}
	}
	return 0
}

func lastLines(s string, n int) string {
	lines := strings.Split(strings.TrimSpace(s), "\n")
	if len(lines) > n {
		lines = lines[len(lines)-n:]
	}
	return strings.Join(lines, " | ")
}

// Diff returns a short line diff of want and got.
func Diff(want, got string) string {
	wl, gl := strings.Split(want, "\n"), strings.Split(got, "\n")
	var b strings.Builder
	n := 0
	for i := 0; i < max(len(wl), len(gl)) && n < 8; i++ {
		var w, g string
		if i < len(wl) {
			w = wl[i]
		}
		if i < len(gl) {
			g = gl[i]
		}
		if w != g {
			fmt.Fprintf(&b, "line %d:\n  want: %s\n  got:  %s\n", i+1, w, g)
			n++
		}
	}
	return b.String()
}

// PrintTable prints one line per program, one column per mode.
func PrintTable(w *os.File, modes []string, progs []Program, results []Result, withBench bool) {
	by := map[string]map[string]Result{}
	for _, r := range results {
		if by[r.File] == nil {
			by[r.File] = map[string]Result{}
		}
		by[r.File][r.Mode] = r
	}
	files := make([]string, 0, len(by))
	for f := range by {
		files = append(files, f)
	}
	sort.Strings(files)
	fmt.Fprintf(w, "%-16s", "program")
	for _, m := range modes {
		fmt.Fprintf(w, " %-17s", m)
	}
	fmt.Fprintln(w)
	for _, f := range files {
		fmt.Fprintf(w, "%-16s", strings.TrimSuffix(filepath.Base(f), ".go"))
		for _, m := range modes {
			r := by[f][m]
			cell := r.Status
			if withBench && r.NsOp > 0 {
				cell += " " + fmtNs(r.NsOp)
			}
			fmt.Fprintf(w, " %-17s", cell)
		}
		fmt.Fprintln(w)
	}
}

func fmtNs(ns int64) string {
	switch {
	case ns >= 1_000_000:
		return fmt.Sprintf("%.1fms", float64(ns)/1e6)
	case ns >= 1000:
		return fmt.Sprintf("%.1fµs", float64(ns)/1e3)
	}
	return fmt.Sprintf("%dns", ns)
}

// WriteTSV writes the results.
func WriteTSV(path string, results []Result) error {
	var b strings.Builder
	b.WriteString("program\tmode\tstatus\tns_per_op\tns_median\tspread_pct\tdetail\n")
	for _, r := range results {
		st := r.Status
		d := strings.NewReplacer("\t", " ", "\n", " | ").Replace(r.Detail)
		if len(d) > 300 {
			d = d[:300] + "..."
		}
		fmt.Fprintf(&b, "%s\t%s\t%s\t%d\t%d\t%d\t%s\n", strings.TrimSuffix(filepath.Base(r.File), ".go"), r.Mode, st, r.NsOp, r.NsMed, r.Spread, d)
	}
	return os.WriteFile(path, []byte(b.String()), 0o644)
}
